WITH RECURSIVE branch_tree AS (SELECT branch_id, branch_name, parent_branch_id, 1 AS depth FROM branch WHERE parent_branch_id IS NULL UNION ALL SELECT b.branch_id, b.branch_name, b.parent_branch_id, bt.depth + 1 FROM branch b JOIN branch_tree bt ON bt.branch_id = b.parent_branch_id) SELECT bt.branch_id, bt.branch_name, bt.depth, count(u.unit_id)::int AS stock_count FROM branch_tree bt LEFT JOIN donation d ON d.branch_id = bt.branch_id LEFT JOIN blood_unit u ON u.donation_id = d.donation_id AND u.status = 'AVAILABLE' GROUP BY bt.branch_id, bt.branch_name, bt.depth ORDER BY bt.depth, bt.branch_name;
